fn permutations(values: &[i32]) -> Vec<Vec<i32>> {
    fn choose(values: &[i32], used: &mut [bool], path: &mut Vec<i32>, out: &mut Vec<Vec<i32>>) {
        if path.len() == values.len() {
            out.push(path.clone());
            return;
        }
        for i in 0..values.len() {
            if !used[i] {
                used[i] = true;
                path.push(values[i]);
                choose(values, used, path, out);
                path.pop();
                used[i] = false;
            }
        }
    }
    let mut out = Vec::new();
    choose(
        values,
        &mut vec![false; values.len()],
        &mut Vec::new(),
        &mut out,
    );
    out
}
fn permutation_count(values: &[i32]) -> usize {
    permutations(values).len()
}

fn main() {
    let result = permutation_count(&[1, 2, 3]).to_string();
    println!("{result}");
}

